<template>
  <div class="detail-page">
    <el-card shadow="never" class="!border-none"><el-form :model="filters" inline class="filter-form"><el-form-item label="经销商"><el-select v-model="filters.dealer" clearable placeholder="请选择经销商"><el-option v-for="item in dealers" :key="item" :label="item" :value="item" /></el-select></el-form-item><el-form-item label="核销时间"><el-date-picker v-model="filters.dateRange" type="daterange" value-format="YYYY-MM-DD" range-separator="至" start-placeholder="开始日期" end-placeholder="结束日期" /></el-form-item><el-form-item><el-button type="primary" @click="resetPage">查询</el-button><el-button @click="resetFilters">重置</el-button><el-button :icon="Download" @click="exportData">导出</el-button></el-form-item></el-form></el-card>
  <el-card shadow="never" class="!border-none mt-4"><template #header><div class="heading"><el-tabs v-model="filters.status" @tab-change="resetPage"><el-tab-pane v-for="status in tabs" :key="status" :label="status" :name="status" /></el-tabs><el-button type="primary" @click="batchRedeem">批量兑奖</el-button></div></template><el-table :data="pagedRows" stripe table-layout="fixed"><el-table-column prop="totalBatch" label="总批次" min-width="130" /><el-table-column prop="batchNo" label="批次号" min-width="130" /><el-table-column prop="codeId" label="奖码ID" min-width="150" /><el-table-column prop="prize" label="中奖奖项" min-width="170" /><el-table-column prop="dealer" label="核销经销商" min-width="140" /><el-table-column prop="status" label="状态" min-width="100" /><el-table-column prop="redeemedAt" label="核销时间" min-width="170" /><el-table-column label="操作" width="100" fixed="right"><template #default="{ row }"><el-button v-if="row.status === '待核销'" link type="primary" @click="redeem(row)">兑奖</el-button><span v-else class="muted">已核销</span></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="page" background layout="total, prev, pager, next" :total="filteredRows.length" /></div></el-card><el-dialog v-model="batchVisible" title="批量兑奖" width="560px"><el-form :model="batchForm" label-width="100px"><el-form-item label="核销经销商" required><el-select v-model="batchForm.dealer" placeholder="请选择经销商"><el-option v-for="item in dealers" :key="item" :label="item" :value="item" /></el-select></el-form-item><el-form-item label="核销时间段" required><el-date-picker v-model="batchForm.dateRange" type="daterange" value-format="YYYY-MM-DD" range-separator="至" start-placeholder="开始日期" end-placeholder="结束日期" /></el-form-item></el-form><template #footer><el-button @click="batchVisible = false">取消</el-button><el-button type="primary" @click="confirmBatchRedeem">确认兑奖</el-button></template></el-dialog></div>
</template>
<script lang="ts" setup name="prizeDetails">
import { Download } from '@element-plus/icons-vue'
const tabs = ['全部', '待核销', '已核销']; const dealers = ['华东经销商', '华南经销商', '华北经销商', '西南经销商']; const filters = reactive({ dealer: '', dateRange: [] as string[], status: '全部' }); const page = ref(1); const pageSize = 10; const batchVisible = ref(false); const batchForm = reactive({ dealer: '', dateRange: [] as string[] })
const rows = reactive<any[]>(Array.from({ length: 26 }, (_, i) => { const day = String(28 - i % 20).padStart(2, '0'); return { totalBatch: `ZP202608${21 + i % 8}`, batchNo: `JM202608${101 + i % 12}`, codeId: `JM202608${101 + i % 12}-${String(i + 1).padStart(4, '0')}`, prize: '加5元兑换50元迈极炫一包', dealer: dealers[i % dealers.length], status: i % 2 ? '待核销' : '已核销', createdAt: `2026-08-${day}`, redeemedAt: i % 2 ? '-' : `2026-08-${day} 14:20:00` } }))
const filteredRows = computed(() => rows.filter(r => { const inDate = filters.dateRange.length !== 2 || (r.redeemedAt !== '-' && r.redeemedAt.slice(0, 10) >= filters.dateRange[0] && r.redeemedAt.slice(0, 10) <= filters.dateRange[1]); return (!filters.dealer || r.dealer === filters.dealer) && (filters.status === '全部' || r.status === filters.status) && inDate })); const pagedRows = computed(() => filteredRows.value.slice((page.value - 1) * pageSize, page.value * pageSize)); const resetPage = () => { page.value = 1 }; const resetFilters = () => { Object.assign(filters, { dealer: '', dateRange: [], status: '全部' }); resetPage() }
const redeem = async (row: any) => { try { await ElMessageBox.confirm(`确认将奖码 ${row.codeId} 标记为已核销吗？`, '兑奖确认'); row.status = '已核销'; row.redeemedAt = '2026-08-28 17:30:00'; ElMessage.success('兑奖成功') } catch {} }; const batchRedeem = () => { batchForm.dealer = filters.dealer || ''; batchForm.dateRange = []; batchVisible.value = true }; const confirmBatchRedeem = () => { if (!batchForm.dealer || batchForm.dateRange.length !== 2) return ElMessage.warning('请选择核销经销商和核销时间段'); const targets = rows.filter(r => r.status === '待核销' && r.dealer === batchForm.dealer && r.createdAt >= batchForm.dateRange[0] && r.createdAt <= batchForm.dateRange[1]); targets.forEach(r => { r.status = '已核销'; r.redeemedAt = `${batchForm.dateRange[1]} 17:30:00` }); batchVisible.value = false; ElMessage.success(`已批量兑奖 ${targets.length} 条`); resetPage() }
const exportData = () => { const data = [['总批次', '批次号', '奖码ID', '中奖奖项', '核销经销商', '状态', '核销时间'], ...filteredRows.value.map(r => [r.totalBatch, r.batchNo, r.codeId, r.prize, r.dealer, r.status, r.redeemedAt])]; const url = URL.createObjectURL(new Blob([`\ufeff${data.map(r => r.join(',')).join('\n')}`], { type: 'text/csv;charset=utf-8;' })); const a = document.createElement('a'); a.href = url; a.download = '中奖明细.csv'; a.click(); URL.revokeObjectURL(url) }
</script>
<style scoped>.filter-form{margin-bottom:-18px}.filter-form :deep(.el-input),.filter-form :deep(.el-select){width:220px}.filter-form :deep(.el-date-editor){width:280px}.heading{display:flex;align-items:center;justify-content:space-between}.heading :deep(.el-tabs){margin-bottom:-1px}.heading :deep(.el-tabs__header){margin:0}.heading :deep(.el-tabs__nav-wrap::after){display:none}.heading :deep(.el-tabs__item){height:38px;padding:0 16px;line-height:38px}.pagination{display:flex;justify-content:flex-end;margin-top:16px}.muted{color:var(--el-text-color-secondary)}@media(max-width:700px){.filter-form :deep(.el-input),.filter-form :deep(.el-select),.filter-form :deep(.el-date-editor){width:100%}.filter-form :deep(.el-form-item){width:100%;margin-right:0}}
</style>
